//! Wi-Fi over Messenger (`idl/wifi.midl`, docs/architecture/wifi.md):
//!
//! * [`Radio`]: the client side of `os.lazy.net.wifi.hw.v1`, a radio driver
//!   (`wifid`, `wifisim`) as `wlanmd` uses it; radios are found by
//!   [`radios`] under `os.lazy.net.wifi.hw/<ifname>`;
//! * [`Client`]: the client side of `os.lazy.net.wifi.v1`, the station
//!   manager `wlanmd` as `wifictl` and the front ends use it.
//!
//! The stubs and both clients are generated by `midlc`; this module adds the
//! names, the paged scan read and the two calls that carry a secret
//! ([`set_key`], [`add_network`]), which keep a buffer of their own so no
//! stray copy of the key is left behind.

use alloc::format;
use alloc::string::String;
use alloc::vec::Vec;

use libmessenger::client::{CallError, Connection, Deadline};
use libmessenger::{Header, Object, Parcel, VERSION};

use super::client::{call_error, Native};
use super::{registry, Endpoint, Result};

type CallResult<T> = core::result::Result<T, CallError>;

/// The generated `os.lazy.net.wifi.hw.v1` stubs.
pub use messenger_generated::os_lazy_net_wifi_hw_v1 as hw;
/// The generated `os.lazy.net.wifi.v1` stubs.
pub use messenger_generated::os_lazy_net_wifi_v1 as api;

/// The station manager's registered name.
pub const NAME: &str = netpolicy::WIFI_SERVICE_NAME;

/// The registered name of the radio serving `ifname`.
pub fn hw_name(ifname: &str) -> String {
    format!("{}/{ifname}", netpolicy::WIFI_HW_NAME_PREFIX)
}

/// The interface name inside a radio's registered name, if `name` is one.
pub fn hw_ifname_of(name: &str) -> Option<&str> {
    name.strip_prefix(netpolicy::WIFI_HW_NAME_PREFIX)?
        .strip_prefix('/')
        .filter(|ifname| devmatch::valid_ifname(ifname))
}

/// A radio registered right now, held by a Wi-Fi driver identity (the
/// registry allows no one else; this checks again what it lists).
pub fn radios() -> Result<Vec<String>> {
    let mut names: Vec<String> = registry::list()?
        .into_iter()
        .filter(|entry| {
            let (Ok(uid), Ok(label)) = (
                u32::try_from(entry.owner_uid),
                u32::try_from(entry.owner_label),
            ) else {
                return false;
            };
            netpolicy::may_register_wifi_hw_name(uid, label, entry.owner_session)
        })
        .filter_map(|entry| hw_ifname_of(&entry.name).map(String::from))
        .collect();
    names.sort();
    names.dedup();
    Ok(names)
}

fn parcel(interface: u64, method: u32, body: Vec<u8>, objects: Vec<Object>) -> Parcel {
    Parcel {
        header: Header {
            version: VERSION,
            flags: 0,
            interface_id: interface,
            method,
            txn_id: 0,
            reply_to: 0,
            deadline_ns: 0,
        },
        body,
        objects,
    }
}

/// A `wifi.v1` parcel of `method` carrying `body` (the service's replies).
pub fn reply(method: u32, body: Vec<u8>) -> Parcel {
    parcel(api::INTERFACE_ID, method, body, Vec::new())
}

/// Room for the reply to a request that carried a secret: those replies
/// are empty or a structured error.
const SECRET_REPLY: usize = 1024;

/// Call with a request that carries a secret (a temporal key, a
/// passphrase): encode it here into a buffer sized up front (a growing one
/// would leave copies behind in freed memory), send it, and wipe the
/// parcel's body and the encoded bytes whatever the outcome. The generated
/// client cannot do this (it moves the body through growing buffers), so the
/// two secret calls frame their request here, on the connection.
fn call_secret(
    conn: &Connection<Native>,
    interface: u64,
    method: u32,
    body: Vec<u8>,
    within: Deadline,
) -> CallResult<Parcel> {
    let mut request = Connection::<Native>::request(interface, method, 0, body, Vec::new());
    let mut bytes = Vec::with_capacity(request.body.len() + 256);
    let encoded = request.encode(&mut bytes);
    wipe_bytes(&mut request.body);
    let result = match encoded {
        Ok(()) => conn
            .connect()
            .map_err(CallError::Transport)
            .and_then(|handle| {
                let mut buf = [0u8; SECRET_REPLY];
                Endpoint::from_raw(handle)
                    .call_bytes_with(
                        &bytes,
                        &mut buf,
                        Some(within.absolute_ticks(crate::sys::clock())),
                    )
                    .map_err(call_error)
            }),
        Err(error) => Err(CallError::bad_request(error)),
    };
    wipe_bytes(&mut bytes);
    Connection::<Native>::check(result?)
}

/// Scrub `bytes` with volatile writes so compiler optimizations cannot eliminate the zeroing.
pub fn wipe_bytes(bytes: &mut [u8]) {
    for byte in bytes.iter_mut() {
        // SAFETY: `byte` is a valid, aligned, exclusive reference.
        unsafe { core::ptr::write_volatile(byte, 0) };
    }
}

/// Wipe a secret held in a `String` and drop it.
pub fn wipe(text: String) {
    let mut bytes = text.into_bytes();
    wipe_bytes(&mut bytes);
}

/// A radio, as its one client sees it: the generated client of
/// `os.lazy.net.wifi.hw.v1`. Dropping it releases the handle obtained by
/// name. Its bound for a call is the interface's `default deadline`, so a
/// wedged driver cannot hang `wlanmd`.
pub type Radio = hw::Client<Native>;

/// Entries one `ScanResults` page asks for: a page of beacons stays far
/// below the reply buffer.
pub const SCAN_PAGE: u32 = 16;
/// Entries read from one scan at most.
pub const SCAN_MAX_ENTRIES: usize = 512;

/// Resolve the radio serving `ifname`, once (it is `wlanmd` that decides
/// when to try again).
pub fn connect_radio(ifname: &str) -> CallResult<Radio> {
    let radio = Radio::from_connection(Connection::named(Native, hw_name(ifname)));
    radio
        .connection()
        .try_connect()
        .map_err(CallError::Transport)?;
    Ok(radio)
}

/// `Scan` every channel, actively, probing for `ssids`.
pub fn scan_all(radio: &Radio, ssids: Vec<Vec<u8>>) -> CallResult<u32> {
    radio.scan(&hw::ScanRequest {
        channels: Vec::new(),
        band: u32::MAX,
        ssids,
        active: true,
        dwell_ms: 0,
    })
}

/// Every entry of scan `scan_id`, page by page, at most [`SCAN_MAX_ENTRIES`].
pub fn scan_results(radio: &Radio, scan_id: u32) -> CallResult<Vec<hw::ScanEntry>> {
    let mut out = Vec::new();
    loop {
        let page = radio.scan_results(scan_id, out.len() as u32, SCAN_PAGE)?;
        let empty = page.results.is_empty();
        out.extend(page.results);
        if !page.more || empty || out.len() >= SCAN_MAX_ENTRIES {
            out.truncate(SCAN_MAX_ENTRIES);
            return Ok(out);
        }
    }
}

/// `Join` the BSS `bssid` on `channel` at 20 MHz.
pub fn join(radio: &Radio, bssid: [u8; 6], channel: u8, band: u32) -> CallResult<()> {
    radio.join(&hw::JoinRequest {
        bssid: bssid.to_vec(),
        channel: u32::from(channel),
        band,
        width: hw::WIDTH_MHZ20,
    })
}

/// `SetKey` with CCMP-128. Every copy of the key this side makes (the
/// arguments, the encoded body, the wire bytes) is wiped as soon as the
/// call returns.
pub fn set_key(
    radio: &Radio,
    kind: u32,
    index: u32,
    key: &[u8],
    rsc: &[u8],
    addr: &[u8],
) -> CallResult<()> {
    let mut args = hw::SetKeyArgs {
        kind,
        index,
        cipher: hw::CIPHER_CCMP128,
        key: key.to_vec(),
        rsc: rsc.to_vec(),
        addr: addr.to_vec(),
    };
    let body = hw::encode_set_key_args(&args).map_err(CallError::bad_request);
    wipe_bytes(&mut args.key);
    call_secret(
        radio.connection(),
        hw::INTERFACE_ID,
        hw::METHOD_SETKEY,
        body?,
        hw::METHOD_SETKEY_DEADLINE,
    )
    .map(|_| ())
}

/// A blocking client of `wlanmd`, generated by `midlc`.
pub type Client = api::Client<Native>;

/// `AddNetwork`; the passphrase crosses once, to `wlanmd`, which hands it to
/// `keyd`. This side's copies of it (the argument, the encoded body, the wire
/// bytes) are wiped before it returns.
pub fn add_network(
    client: &Client,
    profile: api::Profile,
    passphrase: Option<String>,
) -> CallResult<String> {
    let mut args = api::AddNetworkArgs {
        profile,
        passphrase,
    };
    let body = api::encode_add_network_args(&args).map_err(CallError::bad_request);
    if let Some(text) = args.passphrase.take() {
        wipe(text);
    }
    let reply = call_secret(
        client.connection(),
        api::INTERFACE_ID,
        api::METHOD_ADDNETWORK,
        body?,
        api::METHOD_ADDNETWORK_DEADLINE,
    )?;
    Ok(api::decode_add_network_reply(&reply.body)
        .map_err(CallError::bad_reply)?
        .id)
}
